#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
WRITTEN_VAR=()    # variable NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)
_ENV_TMP=""
_GH_CHECKED=0
_GH_OK=0

# Remove write_env's temp file on any exit, including Ctrl-C.
_cleanup() { [[ -z "$_ENV_TMP" ]] || rm -f "$_ENV_TMP"; }
trap _cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
  (( _STAGE_INDEX <= TOTAL_STAGES )) || warn "TOTAL_STAGES=$TOTAL_STAGES is lower than the stages written"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes. It returns 1 on no,
# which ends the wizard under set -e, so call it as `if confirm ...; then` or
# `confirm ... || { warn "..."; exit 1; }`.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes (and its '\'' apostrophe escape) or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  else
    value="${value%%[[:space:]]#*}"                  # drop a trailing " # comment"
    value="${value%"${value##*[![:space:]]}"}"       # and trailing whitespace
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Re-prompts on empty input; fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  while :; do
    rc=0; read -e -r -p "$p" input || rc=1
    if (( rc )) && [[ -z "$input" ]]; then return 1; fi
    [[ -z "$input" && -n "$current" ]] && input="$current"
    [[ -z "$input" ]] || break
    warn "a value is required"
  done
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc
  current=$(_existing "$key" || true)
  while :; do
    if [[ -n "$current" ]]; then
      printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
    else
      printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
    fi
    rc=0; read -rs input || rc=1
    printf '\n'
    if (( rc )) && [[ -z "$input" ]]; then return 1; fi
    [[ -z "$input" && -n "$current" ]] && input="$current"
    [[ -z "$input" ]] || break
    warn "a value is required"
  done
  printf -v "$key" '%s' "$input"
}

# _env_git_guard REAL_PATH: once per run, refuse an ENV_FILE that git tracks, and
# one git does not ignore until the human adds it to .gitignore. There is no
# override. REAL_PATH is ENV_FILE with any symlink resolved, so the checks apply
# to the file that receives the values. Outside a git work tree it only warns.
_env_git_guard() {
  [[ -n "${_ENV_GIT_CHECKED:-}" ]] && return 0
  local real="${1:-$ENV_FILE}" dir base
  dir=$(dirname -- "$real"); base=$(basename -- "$real")
  if git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
    if git -C "$dir" ls-files --error-unmatch -- "$base" >/dev/null 2>&1; then
      warn "$ENV_FILE is tracked by git; refusing to write secrets to it"; return 1
    fi
    if ! git -C "$dir" check-ignore -q -- "$base"; then
      warn "$ENV_FILE is not ignored by git; add it to .gitignore before any secret is written."
      pause "Press Enter once it is in .gitignore"
      git -C "$dir" check-ignore -q -- "$base" || { warn "$ENV_FILE is still not ignored; refusing to write secrets to it"; return 1; }
    fi
  else
    warn "not inside a git repo: keep $ENV_FILE out of any repository you create here."
  fi
  _ENV_GIT_CHECKED=1
}

# _resolve_link PATH: readlink -f fallback for systems without it (macOS < 12.3).
_resolve_link() {
  local p="$1" d n=0
  while [[ -L "$p" ]]; do
    (( n++ < 40 )) || return 1   # symlink loop
    d=$(cd -P -- "$(dirname -- "$p")" && pwd) || return 1
    p=$(readlink -- "$p") || return 1
    [[ "$p" == /* ]] || p="$d/$p"
  done
  d=$(cd -P -- "$(dirname -- "$p")" && pwd) || return 1
  printf '%s/%s' "$d" "$(basename -- "$p")"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600, keeps an
# existing file's mode, offers chmod 600 when other users can read it, and
# replaces it atomically. Writes through a symlinked ENV_FILE to its real file.
# Values use shell single quotes (an apostrophe becomes '\''), which `source`
# reads back exactly. Refuses a git-tracked or unignored file. On failure the
# file is unchanged.
write_env() {
  local key="$1" value="$2" target="$ENV_FILE" perms rc=0 sq="'\\''"
  if [[ -L "$target" ]]; then
    target=$(readlink -f -- "$ENV_FILE" 2>/dev/null || _resolve_link "$ENV_FILE") || { warn "couldn't resolve symlink $ENV_FILE; $key not written"; return 1; }
  fi
  _env_git_guard "$target" || { warn "$key not written"; return 1; }
  [[ -e "$target" ]] || (umask 077 && : > "$target")
  perms=$(ls -ld "$target")
  if [[ -z "${_ENV_MODE_CHECKED:-}" && ( "${perms:4:1}" == r || "${perms:7:1}" == r ) ]]; then
    _ENV_MODE_CHECKED=1
    warn "$ENV_FILE is readable by other users."
    confirm "Restrict it to you (chmod 600)?" && chmod 600 "$target"
  fi
  _ENV_TMP=$(mktemp "$(dirname -- "$target")/.wizard-env.XXXXXX") || return 1
  cp -p "$target" "$_ENV_TMP" || { rm -f "$_ENV_TMP"; _ENV_TMP=""; return 1; }   # copies the mode
  grep -vE "^${key}=" "$target" > "$_ENV_TMP" || rc=$?    # 1 = no other lines, 2 = read error
  if (( rc > 1 )) || ! printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$_ENV_TMP" || ! mv -f -- "$_ENV_TMP" "$target"; then
    rm -f "$_ENV_TMP"; _ENV_TMP=""; warn "couldn't write $key to $ENV_FILE; it is unchanged"; return 1
  fi
  _ENV_TMP=""
  [[ "$(_existing "$key" || true)" == "$value" ]] || warn "$key did not read back unchanged from $ENV_FILE; check it by hand"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# _check_gh_repo runs once, before the first gh write: it shows the repository
# gh will write to and asks the human to confirm it. Returns 1 if not confirmed.
_check_gh_repo() {
  if [[ "$_GH_CHECKED" == 0 ]]; then
    _GH_CHECKED=1
    local repo
    repo=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null) || repo=""
    if [[ -n "$repo" ]] && confirm "Write GitHub secrets and variables to $repo?"; then _GH_OK=1; fi
  fi
  [[ "$_GH_OK" == 1 ]]
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2" err="gh not installed or not authenticated"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    _check_gh_repo || { SKIPPED+=("GitHub secret $name (target repository not confirmed; set it manually: gh secret set $name)"); warn "skipped GitHub secret $name: target repository not confirmed"; return; }
    # The value goes in on stdin, so gh's stderr cannot echo it.
    if err=$(printf '%s' "$value" | gh secret set "$name" 2>&1 >/dev/null); then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
    err="${err%%$'\n'*}"
  fi
  SKIPPED+=("GitHub secret $name (${err:-gh failed}; set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: ${err:-gh failed}; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2" err="gh not installed or not authenticated"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    _check_gh_repo || { SKIPPED+=("GitHub variable $name (target repository not confirmed; set it manually: gh variable set $name)"); warn "skipped GitHub variable $name: target repository not confirmed"; return; }
    if err=$(gh variable set "$name" --body "$value" 2>&1 >/dev/null); then
      WRITTEN_VAR+=("$name")
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
    err="${err%%$'\n'*}"
  fi
  SKIPPED+=("GitHub variable $name (${err:-gh failed}; set it manually: gh variable set $name)")
  warn "skipped GitHub variable $name: ${err:-gh failed}; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  if (( ${#SKIPPED[@]} )); then
    printf '\n%s%s  ⚠ Setup incomplete: %s item(s) still to do%s\n' "$BOLD" "$YELLOW" "${#SKIPPED[@]}" "$RESET"
  else
    printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  (( ${#WRITTEN_VAR[@]} ))    && note "set ${#WRITTEN_VAR[@]} GitHub variable(s): ${WRITTEN_VAR[*]}"
  (( _STAGE_INDEX == TOTAL_STAGES )) || warn "TOTAL_STAGES=$TOTAL_STAGES but $_STAGE_INDEX stage(s) ran; fix TOTAL_STAGES"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=1

banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
if confirm "Also store the secret key as a GitHub Actions secret for CI?"; then
  set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
fi
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
